/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();
/**
 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
 */
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, UserId } from "@/types/common";
import type { Actor, Invitation, Member } from "@/types/member";

/** Token bucket protecting the invite mailer from being used as a spam relay. */
const INVITE_BUCKET = "member:invite";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) +
    (await invitationRepo.countPendingInvitations(input.orgId));

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const existing = await memberRepo.findMember(invitation.orgId, userId);
  if (existing) return existing;

  const member = await memberRepo.insertMember(
    invitation.orgId,
    userId,
    invitation.role,
    invitation.invitedBy,
  );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    toIsoTimestamp(new Date()),
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo
      .listPendingInvitations(actor.orgId)
      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
    "Invitation",
    invitationId,
  );

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: previous.role === "owner" ? "admin" : previous.role,
  });
}
/**
 * Audit-log writer and reader. Subscribes to the whole event bus and records one row per domain event.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, toCsv
 */
import { toCsv } from "@/lib/csv";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { activityResource } from "./_support";
import type { ActivityFilterInput, ExportActivityInput } from "@/schemas/activity";
import type {
  ActivityAction,
  ActivityEvent,
  ActivityGroup,
  ActivitySubjectKind,
} from "@/types/activity";
import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

export type ActivityRecordInput = {
  actorId: UserId | null;
  subjectKind: ActivitySubjectKind;
  subjectId: string;
  projectId: ProjectId | null;
  summary: string;
  metadata?: Readonly<Record<string, string | number | boolean | null>>;
};

/** Columns of the audit-log CSV export, in the order the file lists them. */
const EXPORT_COLUMNS = [
  "occurredAt",
  "action",
  "actorId",
  "subjectKind",
  "subjectId",
  "summary",
] as const;

/**
 * Appends one audit row. Deliberately takes no `Actor`: the writer is usually
 * an event handler running outside a request, and the row's `actorId` comes
 * from the event payload rather than from an authenticated principal.
 */
export async function record(
  orgId: OrgId,
  action: ActivityAction,
  input: ActivityRecordInput,
): Promise<ActivityEvent> {
  return activityRepo.insertActivity({
    orgId,
    action,
    actorId: input.actorId,
    subjectKind: input.subjectKind,
    subjectId: input.subjectId,
    projectId: input.projectId,
    summary: input.summary,
    metadata: input.metadata ?? {},
    occurredAt: toIsoTimestamp(new Date()),
  });
}

export async function listActivity(
  actor: Actor,
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:read", activityResource(input.orgId));
  return activityRepo.listActivity(input);
}

/** Groups a feed page by calendar day, newest day first. */
export function groupByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = event.occurredAt.slice(0, 10);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => (a < b ? 1 : -1))
    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
}

/**
 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
 * for the role, and on the `csv_export` flag for the plan.
 */
export async function exportActivity(
  actor: Actor,
  input: ExportActivityInput,
): Promise<string> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));

  const org = await orgRepo.findOrgById(input.orgId);
  const flagEnabled = isEnabled("csv_export", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.format === "csv" && !flagEnabled) {
    throw new Error("CSV export is not included in this plan");
  }

  const page = await activityRepo.listActivity({
    orgId: input.orgId,
    since: input.since,
    until: input.until,
    limit: 100,
    cursor: null,
  });

  if (input.format === "json") {
    return JSON.stringify(page.items, null, 2);
  }

  return toCsv(
    page.items.map((event) => ({
      occurredAt: event.occurredAt,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      summary: event.summary,
    })),
    [...EXPORT_COLUMNS],
  );
}

/**
 * Attaches one handler per audited event type. Called once from
 * `event-registry`; the returned function detaches all of them, which is what
 * the test suite uses to keep the bus clean between cases.
 */
export function registerActivityListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("project.created", (payload) =>
      record(payload.orgId, "project.created", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: `Created project ${payload.name}`,
      }).then(() => undefined),
    ),
    subscribe("project.archived", (payload) =>
      record(payload.orgId, "project.archived", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: `Archived project with ${payload.issuesArchived} issues`,
      }).then(() => undefined),
    ),
    subscribe("issue.created", (payload) =>
      record(payload.orgId, "issue.created", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Created issue "${payload.title}"`,
        metadata: { priority: payload.priority },
      }).then(() => undefined),
    ),
    subscribe("issue.status_changed", (payload) =>
      record(payload.orgId, "issue.status_changed", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Status ${payload.from} → ${payload.to}`,
        metadata: { from: payload.from, to: payload.to },
      }).then(() => undefined),
    ),
    subscribe("issue.assigned", (payload) =>
      record(payload.orgId, "issue.assigned", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Assigned to ${payload.assigneeId}`,
      }).then(() => undefined),
    ),
    subscribe("comment.created", (payload) =>
      record(payload.orgId, "comment.created", {
        actorId: payload.actorId,
        subjectKind: "comment",
        subjectId: payload.commentId,
        projectId: null,
        summary: `Commented on issue ${payload.issueId}`,
      }).then(() => undefined),
    ),
    subscribe("member.invited", (payload) =>
      record(payload.orgId, "member.invited", {
        actorId: payload.actorId,
        subjectKind: "member",
        subjectId: payload.email,
        projectId: null,
        summary: `Invited ${payload.email} as ${payload.role}`,
      }).then(() => undefined),
    ),
    subscribe("member.role_changed", (payload) =>
      record(payload.orgId, "member.role_changed", {
        actorId: payload.actorId,
        subjectKind: "member",
        subjectId: payload.memberId,
        projectId: null,
        summary: `Role ${payload.from} → ${payload.to}`,
      }).then(() => undefined),
    ),
    subscribe("billing.plan_changed", (payload) =>
      record(payload.orgId, "billing.plan_changed", {
        actorId: payload.actorId,
        subjectKind: "subscription",
        subjectId: payload.orgId,
        projectId: null,
        summary: `Plan ${payload.from} → ${payload.to}`,
      }).then(() => undefined),
    ),
  ];

  return () => {
    for (const off of offs) off();
  };
}

