import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let counter = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

async function freshTenant(): Promise<Tenant> {
  counter += 1;
  return createTenant(`ws${counter}`);
}

async function deleted(tenant: Tenant): Promise<Tenant> {
  await deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
