describe("the retention sweep", () => {
  it("purges every trace of an expired workspace and nothing else", async () => {
    const doomed = await freshTenant();
    const recent = await freshTenant();
    const live = await freshTenant();

    const issue = await issueService.createIssue(
      doomed.actors.member,
      issueInput(doomed.org.id, doomed.project.id, { title: "Doomed" }),
    );
    await usageRepo.recomputeUsage(doomed.org.id);
    await usageRepo.recomputeUsage(recent.org.id);
    await searchRepo.upsertSearchDocument(doomed.org.id, {
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: doomed.project.id,
      content: "doomed",
    } as never);
    const session = await sessionRepo.createSession(
      doomed.userIds.owner,
      hashToken("s"),
      toIsoTimestamp(new Date(Date.now() + MS_PER_DAY)),
    );
    getDb()
      .$client.prepare("UPDATE sessions SET active_org_id = ? WHERE user_id = ?")
      .run(doomed.org.id, session.userId);
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: doomed.org.id, url: "https://example.test/h", eventTypes: [] } as never,
      "s",
    );
    await webhookRepo.enqueueDelivery(doomed.org.id, endpoint.id, "x", "{}");

    await deleted(doomed);
    await deleted(recent);
    deletedAgo(doomed.org.id, WINDOW_MS + 1_000);
    deletedAgo(recent.org.id, WINDOW_MS - 60_000);

    await runCleanupArchivedJob(new Date());

    const client = getDb().$client;
    const tables = client
      .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
      .all() as { name: string }[];
    for (const { name } of tables) {
      const columns = client.prepare(`PRAGMA table_info("${name}")`).all() as { name: string }[];
      if (!columns.some((column) => column.name === "org_id")) continue;
      const left = client
        .prepare(`SELECT count(*) AS n FROM "${name}" WHERE org_id = ?`)
        .get(doomed.org.id) as { n: number };
      expect(left.n, name).toBe(0);
    }
    expect(await orgRepo.findOrgById(doomed.org.id)).toBeNull();
    expect(await userRepo.findUserById(doomed.userIds.owner)).not.toBeNull();
    expect(
      (client.prepare("SELECT active_org_id AS a FROM sessions WHERE user_id = ?").get(session.userId) as { a: string | null }).a,
    ).toBeNull();

    await expect(
      restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    const reused = await createOrganization(doomed.userIds.owner, {
      name: "Reborn",
      slug: doomed.org.slug,
      plan: "free",
    });
    expect(reused.slug).toBe(doomed.org.slug);

    // Inside the window, and live, are untouched.
    expect((await orgRepo.findOrgById(recent.org.id))?.archivedAt).not.toBeNull();
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();
    expect(await usageRepo.getUsage(recent.org.id)).toBeTruthy();
    await restoreOrganization(recent.userIds.owner, recent.org.id);
  });
});

