/**
 * Deleting a workspace is a grace period, then a purge: the owner can restore
 * it for `DELETED_WORKSPACE_RETENTION_DAYS`, it is inert while deleted, and the
 * retention sweep removes every trace of it once the window has closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { getDb } from "@/server/db";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  listOrganizationsForUser,
  resolveOrgBySlug,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let counter = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

async function freshTenant(): Promise<Tenant> {
  counter += 1;
  return createTenant(`ws${counter}`);
}

async function deleted(tenant: Tenant): Promise<Tenant> {
  await deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
  return tenant;
}

/** Rewinds the deletion so it happened `ago` milliseconds before now. */
function deletedAgo(orgId: OrgId, ago: number): void {
  getDb()
    .$client.prepare("UPDATE organizations SET archived_at = ? WHERE id = ?")
    .run(new Date(Date.now() - ago).toISOString(), orgId);
}

describe("deleteOrganization", () => {
  it("publishes organization.deleted and audits it", async () => {
    const tenant = await freshTenant();
    const seen = capture("organization.deleted");

    await deleted(tenant);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: tenant.org.slug,
    });

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 10,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.deleted",
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });
  });

  it("refuses to delete a workspace that is already deleted", async () => {
    const tenant = await deleted(await freshTenant());
    const seen = capture("organization.deleted");

    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(seen).toHaveLength(0);
  });

  it("keeps its guards", async () => {
    const tenant = await freshTenant();

    await expect(
      deleteOrganization(tenant.actors.admin, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: "not-the-slug",
      }),
    ).rejects.toThrow(/confirmation/);
  });
});

describe("a deleted workspace", () => {
  it("cannot be signed in to, is not listed and keeps its slug reserved", async () => {
    const tenant = await deleted(await freshTenant());
    const principal = {
      userId: tenant.userIds.owner,
      email: "x@y.test",
      activeOrgId: tenant.org.id,
      expiresAt: toIsoTimestamp(new Date(Date.now() + MS_PER_DAY)),
    };

    await expect(resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(resolveOrgBySlug(tenant.org.slug)).resolves.toBeNull();
    expect(
      (await listOrganizationsForUser(tenant.userIds.owner)).map((o) => o.id),
    ).not.toContain(tenant.org.id);

    const again = await createOrganization(tenant.userIds.owner, {
      name: "Same name",
      slug: tenant.org.slug,
      plan: "free",
    });
    expect(again.slug).not.toBe(tenant.org.slug);
  });

  it("gets no notifications", async () => {
    const tenant = await deleted(await freshTenant());

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
      title: "t",
      body: "b",
      href: "/x",
      actorId: null,
    });
    expect(rows).toEqual([]);
  });

  it("cannot have an invitation accepted, and the invitation stays pending", async () => {
    const tenant = await freshTenant();
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@ws.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken("tok"),
    );
    const newcomer = await userRepo.insertUser({
      email: "newcomer@ws.test",
      name: "New",
      passwordHash: "seed",
    });
    await deleted(tenant);

    await expect(
      acceptInvitation(newcomer.id, { token: "tok" }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toContain(invitation.id);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const member = await acceptInvitation(newcomer.id, { token: "tok" });
    expect(member.orgId).toBe(tenant.org.id);
  });
});

describe("jobs leave a deleted workspace alone", () => {
  it("skips overdue alerts, usage recomputes, trial expiry and reindexing", async () => {
    resetOverdueTracking();
    const tenant = await freshTenant();
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );
    await usageRepo.recomputeUsage(tenant.org.id);
    getDb()
      .$client.prepare(
        "UPDATE subscriptions SET status = 'trialing', current_period_end = ? WHERE org_id = ?",
      )
      .run("2026-01-02T00:00:00.000Z", tenant.org.id);
    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    await deleted(tenant);

    const overdue = capture("issue.overdue");
    const plan = capture("billing.plan_changed");
    const now = new Date("2026-06-01T07:00:00.000Z");

    await runOverdueIssueJob(now);
    await runUsageRollupJob(now);
    await runTrialExpiryJob(now);
    const reindexResult = await runSearchReindexJob(tenant.org.id);

    expect(overdue.filter((e) => e.orgId === tenant.org.id)).toHaveLength(0);
    expect(plan.filter((e) => e.orgId === tenant.org.id)).toHaveLength(0);
    expect(reindexResult.processed).toBe(0);
    expect(await usageRepo.getUsage(tenant.org.id)).toEqual(usageBefore);
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("trialing");

    // Restored, the very same work resumes.
    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await runOverdueIssueJob(now);
    expect(overdue.filter((e) => e.orgId === tenant.org.id)).toHaveLength(1);
    await runTrialExpiryJob(now);
    expect(plan.filter((e) => e.orgId === tenant.org.id)).toHaveLength(1);
  });

  it("fails its pending webhook deliveries instead of delivering them", async () => {
    const tenant = await freshTenant();
    const endpoint = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created"],
      },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );
    await deleted(tenant);

    await runWebhookDeliveryJob(new Date());

    const row = getDb()
      .$client.prepare("SELECT status FROM webhook_deliveries WHERE id = ?")
      .get(delivery.id) as { status: string };
    expect(row.status).toBe("failed");
  });
});

