    const reindexResult = await runSearchReindexJob(tenant.org.id);

    expect(overdue.filter((e) => e.orgId === tenant.org.id)).toHaveLength(0);
    expect(plan.filter((e) => e.orgId === tenant.org.id)).toHaveLength(0);
    expect(reindexResult.processed).toBe(0);
    expect(await usageRepo.getUsage(tenant.org.id)).toEqual(usageBefore);
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("trialing");

    // Restored, the very same work resumes.
    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await runOverdueIssueJob(now);
    expect(overdue.filter((e) => e.orgId === tenant.org.id)).toHaveLength(1);
    await runTrialExpiryJob(now);
    expect(plan.filter((e) => e.orgId === tenant.org.id)).toHaveLength(1);
  });

  it("fails its pending webhook deliveries instead of delivering them", async () => {
    const tenant = await freshTenant();
    const endpoint = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created"],
      },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );
    await deleted(tenant);

    await runWebhookDeliveryJob(new Date());

    const row = getDb()
      .$client.prepare("SELECT status FROM webhook_deliveries WHERE id = ?")
      .get(delivery.id) as { status: string };
    expect(row.status).toBe("failed");
  });
});

describe("restoreOrganization", () => {
  it("lets the owner restore, publishing organization.restored and auditing it", async () => {
    const tenant = await deleted(await freshTenant());
    const seen = capture("organization.restored");

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(restored.archivedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: tenant.org.slug,
    });
    await expect(resolveOrgBySlug(tenant.org.slug)).resolves.not.toBeNull();

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.restored"],
      limit: 10,
      cursor: null,
    });
    expect(page.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });
  });

  it("denies a member who is not the owner", async () => {
    const tenant = await deleted(await freshTenant());

    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("does not know the workspace to a stranger, or when it never existed", async () => {
    const tenant = await deleted(await freshTenant());
    const stranger = await userRepo.insertUser({
      email: "stranger@ws.test",
      name: "Stranger",
      passwordHash: "seed",
    });

    await expect(
      restoreOrganization(stranger.id, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(tenant.userIds.owner, "no-such-org" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("closes the window exactly retention days after the deletion", async () => {
    const tenant = await deleted(await freshTenant());

    deletedAgo(tenant.org.id, WINDOW_MS - 60_000);
    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();

    await deleted(tenant);
    deletedAgo(tenant.org.id, WINDOW_MS);
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await freshTenant();
    const seen = capture("organization.restored");

    const result = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(result).toEqual(tenant.org);
    expect(seen).toHaveLength(0);
  });
});

describe("the retention sweep", () => {
  it("purges every trace of an expired workspace and nothing else", async () => {
    const doomed = await freshTenant();
    const recent = await freshTenant();
    const live = await freshTenant();

    const issue = await issueService.createIssue(
      doomed.actors.member,
      issueInput(doomed.org.id, doomed.project.id, { title: "Doomed" }),
    );
    await usageRepo.recomputeUsage(doomed.org.id);
    await usageRepo.recomputeUsage(recent.org.id);
    await searchRepo.upsertSearchDocument(
      doomed.org.id,
      "issue",
      issue.id,
      "doomed",
      doomed.project.id,
    );
    const session = await sessionRepo.createSession(
      doomed.userIds.owner,
      hashToken("s"),
      toIsoTimestamp(new Date(Date.now() + MS_PER_DAY)),
    );
    getDb()
      .$client.prepare("UPDATE sessions SET active_org_id = ? WHERE user_id = ?")
      .run(doomed.org.id, session.userId);
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: doomed.org.id, url: "https://example.test/h", eventTypes: ["issue.created"] },
      "s",
    );
    await webhookRepo.enqueueDelivery(doomed.org.id, endpoint.id, "x", "{}");

    await deleted(doomed);
    await deleted(recent);
    deletedAgo(doomed.org.id, WINDOW_MS + 1_000);
    deletedAgo(recent.org.id, WINDOW_MS - 60_000);

    await runCleanupArchivedJob(new Date());

    const client = getDb().$client;
    const tables = client
      .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
      .all() as { name: string }[];
    for (const { name } of tables) {
      const columns = client.prepare(`PRAGMA table_info("${name}")`).all() as { name: string }[];
      if (!columns.some((column) => column.name === "org_id")) continue;
      const left = client
        .prepare(`SELECT count(*) AS n FROM "${name}" WHERE org_id = ?`)
        .get(doomed.org.id) as { n: number };
      expect(left.n, name).toBe(0);
    }
    expect(await orgRepo.findOrgById(doomed.org.id)).toBeNull();
    expect(await userRepo.findUserById(doomed.userIds.owner)).not.toBeNull();
    const active = client
      .prepare("SELECT active_org_id AS a FROM sessions WHERE user_id = ?")
      .get(session.userId) as { a: string | null };
    expect(active.a).toBeNull();

    await expect(
      restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    const reused = await createOrganization(doomed.userIds.owner, {
      name: "Reborn",
      slug: doomed.org.slug,
      plan: "free",
    });
    expect(reused.slug).toBe(doomed.org.slug);

    // Inside the window, and live, are untouched.
    expect((await orgRepo.findOrgById(recent.org.id))?.archivedAt).not.toBeNull();
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();
    const restored = await restoreOrganization(recent.userIds.owner, recent.org.id);
    expect(restored.archivedAt).toBeNull();
  });
});

